.darma-loader-ferris-wheel {
  position: relative;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  border: 4px solid var(--loader-color, #6366f1);
  box-sizing: border-box;
  background:
    linear-gradient(var(--loader-color, #6366f1), var(--loader-color, #6366f1)) center / 4px 100% no-repeat,
    linear-gradient(var(--loader-color, #6366f1), var(--loader-color, #6366f1)) center / 100% 4px no-repeat;
  animation: darma-loader-ferris-wheel-spin 3s linear infinite;
}
.darma-loader-ferris-wheel i {
  position: absolute;
  width: 12px;
  height: 9px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-ferris-wheel-spin 3s linear infinite reverse;
}
.darma-loader-ferris-wheel i:nth-child(1) { top: -5px; left: 50%; margin-left: -6px; }
.darma-loader-ferris-wheel i:nth-child(2) { right: -5px; top: 50%; margin-top: -4px; }
.darma-loader-ferris-wheel i:nth-child(3) { bottom: -5px; left: 50%; margin-left: -6px; }
.darma-loader-ferris-wheel i:nth-child(4) { left: -5px; top: 50%; margin-top: -4px; }
@keyframes darma-loader-ferris-wheel-spin { to { transform: rotate(360deg); } }

